import unittest
from unittest.mock import patch
from candidate import factorize
from math import isclose

class TestFactorize(unittest.TestCase):

    @patch('candidate.factorize.math.sqrt')
    def test_factorize_small_prime(self, mock_sqrt):
        mock_sqrt.return_value = 3
        self.assertEqual(factorize(9), [3])

    @patch('candidate.factorize.math.sqrt')
    def test_factorize_small_nonprime(self, mock_sqrt):
        mock_sqrt.return_value = 3
        self.assertEqual(factorize(8), [2, 2, 2])

    @patch('candidate.factorize.math.sqrt')
    def test_factorize_large_prime(self, mock_sqrt):
        mock_sqrt.return_value = 5
        self.assertEqual(factorize(49), [7, 7])

    @patch('candidate.factorize.math.sqrt')
    def test_factorize_product_of_small_primes(self, mock_sqrt):
        mock_sqrt.return_value = 2
        self.assertEqual(factorize(4), [2, 2])

    @patch('candidate.factorize.math.sqrt')
    def test_factorize_product_of_large_and_small_primes(self, mock_sqrt):
        mock_sqrt.return_value = 2
        self.assertEqual(factorize(10), [2, 5])

    @patch('candidate.factorize.math.sqrt')
    def test_factorize_large_nonprime(self, mock_sqrt):
        mock_sqrt.return_value = 4
        self.assertEqual(factorize(16), [2, 2, 2, 2])

    def test_factorize_1(self):
        self.assertEqual(factorize(1), [])

    def test_factorize_non_integer(self):
        with self.assertRaises(TypeError):
            factorize(4.5)

    def test_factorize_negative(self):
        with self.assertRaises(TypeError):
            factorize(-10)

    def test_factorize_zero(self):
        with self.assertRaises(ValueError):
            factorize(0)

    def test_factorize_invalid_type(self):
        with self.assertRaises(TypeError):
            factorize("not_a_number")

    def test_factorize_large_number(self):
        self.assertEqual(factorize(100000), [2, 2, 5, 5, 5, 5])

    def test_factorize_exactly_square_root(self):
        self.assertEqual(factorize(36), [2, 3, 3, 2, 3])

    def test_factorize_with_precision(self):
        self.assertTrue(any(isclose(factorize(100), x) for x in [2, 2, 5, 5]))

if __name__ == '__main__':
    unittest.main()
